<script>
 import { page } from '$app/state';
 import { onMount } from 'svelte';
 import AppShell from './AppShell.svelte'; import Icon from './Icon.svelte'; import StatusIcon from './StatusIcon.svelte'; import { api } from '#lib/api';
 let {tab='overview'}=$props();
 let project=$state(null); let tasks=$state([]); let nodes=$state([]); let messages=$state([]);
 let loading=$state(true); let error=$state(''); let messageText=$state(''); let sending=$state(false);
 let showNewTask=$state(false); let taskDescription=$state(''); let selectedNode=$state(''); let branch=$state('feature/frontend-prototype'); let files=$state(''); let assigning=$state(false); let actionMessage=$state(''); let selectedTask=$state(null);
 let projectTasks=$state([]);
 async function reload() { error=''; try { const [p,t,n,m] = await Promise.all([api.getProject(page.params.project),api.listProjectTasks(page.params.project),api.listNodes(),api.listMessages(page.params.project)]); project=p; projectTasks=t; nodes=n; messages=m; } catch(e) { error=e.message; } finally {loading=false;} }
 onMount(() => { reload(); });
 async function sendMessage() { if(!messageText.trim()||sending)return; sending=true; actionMessage=''; try {messages=[...messages,await api.sendMessage(page.params.project,messageText)];messageText='';}catch(e){actionMessage=e.message;}finally{sending=false;} }
 async function createTask() {if (!project||!taskDescription.trim()||!selectedNode||assigning) return; assigning=true;actionMessage=''; try {const {id}=await api.assignTicket({nodeId:selectedNode,ticket:{'created-at':new Date().toISOString(),'created-by':'keinstein0','git-repo-url':project.repository??'','git-branch-id':branch.trim()||'main','files-of-interest':files.split(',').map(f=>f.trim()).filter(Boolean),description:taskDescription.trim()}});projectTasks=await api.listProjectTasks(project.slug);nodes=await api.listNodes();taskDescription='';files='';showNewTask=false;actionMessage=`Task #${id} assigned`; }catch(e){actionMessage=e.message;}finally{assigning=false;} }
 async function inspectTask(id) { try {selectedTask=await api.getTask(id);}catch(e){actionMessage=e.message;} }
</script>
<AppShell><div class="content-wrap project-content">
 {#if loading}<p class="muted-note" role="status">Loading project…</p>{:else if error}<p class="error-note" role="alert">{error}</p>{:else if project}
 <div class="breadcrumbs"><a href="/">Projects</a><span>/</span>{project.name}</div>
 <div class="project-heading"><div><h1>{project.name}</h1><p>{project.description}</p></div><span class="status-outline">{project.status}</span></div>
 <nav class="project-tabs" aria-label="Project sections"><a class:active={tab==='overview'} href="/projects/{project.slug}"><Icon name="layout"/>Overview</a><a class:active={tab==='conversation'} href="/projects/{project.slug}/conversation"><Icon name="message"/>Conversation</a><a class:active={tab==='tasks'} href="/projects/{project.slug}/tasks"><Icon name="tasks"/>Tasks <span class="count">{projectTasks.length}</span></a></nav>
 {#if tab==='overview'}
 <div class="project-overview"><section class="overview-main"><h2>About</h2><p class="body-copy">{project.details}</p><h2 class="section-heading">Recent tasks</h2><div class="simple-list">{#each projectTasks.slice(0,4) as task}<button class="simple-row selectable-row" onclick={() => inspectTask(task.id)}><StatusIcon status={task.status}/><div><strong>{task.ticket.description}</strong><small>#{task.id} · {nodes.find(n=>n.id===task['node-id'])?.name??task['node-id']}</small></div><span class="row-end">{task.status}</span></button>{/each}</div><a class="section-link" href="/projects/{project.slug}/tasks">View all tasks →</a></section>
 <aside class="overview-side"><h2>Project details</h2><dl class="detail-list"><div><dt><Icon name="activity"/>Status</dt><dd><StatusIcon status={project.status} size={15}/>{project.status}</dd></div><div><dt><Icon name="calendar"/>Created</dt><dd>{project.created}</dd></div><div><dt><Icon name="user"/>Owner</dt><dd>{project.owner}</dd></div><div><dt><Icon name="bot"/>Agents</dt><dd>{nodes.length}</dd></div></dl><h2 class="section-heading">Repository</h2><div class="repo-panel"><Icon name="git" size={20}/><div>{#if project.repository}<a href={project.repository} target="_blank" rel="noreferrer"><strong>{project.repository.replace('https://github.com/','')}</strong></a>{:else}<strong>Not linked</strong>{/if}<small>Git repository</small></div></div></aside></div>
 {:else if tab==='conversation'}
 <section class="conversation-panel" aria-label="Project conversation"><div class="conversation-header"><h2>Conversation</h2><span>Main agent</span></div><div class="conversation-stream">{#each messages as msg (msg.id)}<article class="conversation-message"><div class="message-avatar" class:is-user={msg.author==='You'}><Icon name={msg.author==='You'?'user':'bot'} size={18}/></div><div class="message-content"><div class="message-meta"><strong>{msg.author}</strong><time>{msg.time}</time></div><p>{msg.body}</p></div></article>{/each}</div><form class="compose-area" onsubmit={(e)=>{e.preventDefault();sendMessage();}}><label for="message-input">Message</label><textarea id="message-input" rows="3" bind:value={messageText} aria-label="Message" placeholder="Write a message…"></textarea><div class="form-actions"><button class="primary-button" type="submit" disabled={sending||!messageText.trim()}><Icon name="message"/>{sending?'Sending…':'Send message'}</button></div></form></section>
 {:else if tab==='tasks'}
 <section class="tasks-panel"><div class="tasks-header"><h2>Tasks</h2><div class="header-actions"><span>{projectTasks.length} total</span><button class="secondary-button" onclick={() => showNewTask=!showNewTask}><Icon name="plus"/>New task</button></div></div>
 {#if showNewTask}<form class="ticket-form" onsubmit={(e)=>{e.preventDefault();createTask();}}><label for="task-description">Description</label><textarea id="task-description" bind:value={taskDescription} required rows="3" placeholder="Describe the task"></textarea><div class="ticket-fields"><div><label for="task-agent">Agent</label><select id="task-agent" bind:value={selectedNode} required><option value="">Choose available agent</option>{#each nodes.filter(n=>n.status==='idle'||n.status==='done') as node}<option value={node.id}>{node.name}</option>{/each}</select></div><div><label for="task-branch">Git branch</label><input id="task-branch" bind:value={branch}/></div></div><label for="task-files">Files of interest (comma-separated)</label><input id="task-files" bind:value={files} placeholder="src/main.py, README.md"/><div class="form-actions"><button type="button" class="secondary-button" onclick={() => showNewTask=false}>Cancel</button><button class="primary-button" type="submit" disabled={assigning||!selectedNode||!taskDescription.trim()}>{assigning?'Assigning…':'Assign ticket'}</button></div></form>{/if}
 <div class="tasks-list">{#each projectTasks as task (task.id)}<button class="task-item selectable-row" onclick={() => inspectTask(task.id)}><StatusIcon status={task.status}/><div class="task-info"><strong>{task.ticket.description}</strong><small>#{task.id} · {nodes.find(n=>n.id===task['node-id'])?.name??task['node-id']} · {task.ticket['git-branch-id']}</small></div><span class="task-pill">{task.status}</span></button>{/each}</div></section>
 {/if}
 {#if actionMessage}<p class="action-note" role="status">{actionMessage}</p>{/if}
 {#if selectedTask}<section class="task-detail" aria-label="Task details"><div class="task-detail-heading"><h2>Task #{selectedTask.id}</h2><button class="secondary-button" onclick={() => selectedTask=null}>Close</button></div><p>{selectedTask.ticket.description}</p><dl><dt>Assigned node</dt><dd>{selectedTask['node-id']}</dd><dt>Status</dt><dd>{selectedTask.status}</dd><dt>Branch</dt><dd>{selectedTask.ticket['git-branch-id']}</dd><dt>Files</dt><dd>{selectedTask.ticket['files-of-interest'].join(', ')||'—'}</dd>{#if selectedTask.report}<dt>Report</dt><dd>{selectedTask.report.description}</dd>{/if}</dl></section>{/if}
 {:else}<div class="breadcrumbs"><a href="/">Projects</a></div><h1>Project not found</h1>{/if}
</div></AppShell>
